"""Verify the selected Encoding normalization-query dispatch and enum identity."""
import argparse,hashlib,json,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];EVIDENCE=ROOT/'planning/stage-2/repos/dotj-core/evidence'
def main():
 p=argparse.ArgumentParser();p.add_argument('--jar',type=Path);a=p.parse_args()
 if a.jar is None:a.jar=ROOT/json.loads((EVIDENCE/'foundation-product-candidate-v1.json').read_text(encoding='utf-8'))['jarPath']
 path=EVIDENCE/'generic-encoding-normalization-contract-v10.0.12.json';j=json.loads(path.read_text(encoding='utf-8'));assert j['runtimeVersion']=='10.0.12' and j['coreLibSha256']=='1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678';assert j['oracleSha256']==hashlib.sha256(Path(__file__).with_name('capture-generic-encoding-normalization-contract.ps1').read_bytes()).hexdigest();assert len(j['rows'])==220 and len(j['values'])==4;assert {r['failure']['type'] for r in j['rows'] if r['failure']}=={'System.InvalidOperationException'}
 work=Path('D:/AI/Implementation/dotj Frameworks/verification/generic-encoding-normalization');work.mkdir(parents=True,exist_ok=True);lines=[]
 for r in j['rows']:
  f=r['failure'] or {};lines.append('\t'.join([str(r['kind']),str(int(r['cloned'])),str(r['form']),str(int(r['facade'])),str(int(bool(r['result']))),f.get('type',''),str(f.get('hResult',0)),f.get('message',''),str(r['seen'])]))
 vectors=work/'vectors.tsv';vectors.write_text('\n'.join(lines)+'\n',encoding='ascii');values=work/'values.tsv';values.write_text('\n'.join(r['name']+'\t'+str(r['value']) for r in j['values'])+'\n',encoding='ascii');component=Path(__file__).with_name('generic-encoding-normalization-probe.java');source=work/'GenericEncodingNormalizationProbe.java';source.write_bytes(component.read_bytes());subprocess.run(['javac','--release','21','-cp',str(a.jar),'-d',str(work),str(source)],check=True);result=subprocess.run(['java','-cp',str(a.jar)+';'+str(work),'GenericEncodingNormalizationProbe',str(vectors),str(values)],capture_output=True,text=True);print(result.stdout,end='');print(result.stderr,end='');result.check_returncode();assert 'groups=460' in result.stdout
 bad=work/'OverrideNormalizationFacade.java';bad.write_text('class OverrideNormalizationFacade extends GenericEncodingNormalizationProbe.Minimal {public boolean IsAlwaysNormalized(){return true;}}',encoding='utf-8',newline='\n');result=subprocess.run(['javac','--release','21','-cp',str(a.jar)+';'+str(work),'-d',str(work),str(bad)],capture_output=True,text=True);assert result.returncode!=0 and 'IsAlwaysNormalized' in result.stderr and 'final' in result.stderr
 record=dict(schemaVersion=1,casesPassed=460,nativeCases=220,enumValues=4,nonvirtualFacadeCompileRejection=True,oracleEvidence=path.name,oracleSha256=hashlib.sha256(path.read_bytes()).hexdigest(),consumerSourceSha256=hashlib.sha256(component.read_bytes()).hexdigest(),candidateJarSha256=hashlib.sha256(a.jar.read_bytes()).hexdigest(),qualification='SELECTED_NORMALIZATION_QUERY_DISPATCH_AND_ENUM_IDENTITY_ONLY; NORMALIZATION_TRANSFORMS_FULL_ENUM_ABI_AND_TASK_ACCEPTANCE_OPEN');(EVIDENCE/'generic-encoding-normalization-differential-v1.json').write_text(json.dumps(record,indent=2)+'\n',encoding='utf-8',newline='\n');print('PASS normalization query: 220 native cases, 460 groups and final-facade compile rejection')
if __name__=='__main__':main()
